contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(amount); if (__ESBMC_reverted()) return;

        uint256 beforeBalance = address(c).balance;
        uint256 returned = c.ethBalance(); if (__ESBMC_reverted()) return;

        assert(returned == beforeBalance && returned == address(c).balance);
    }

    receive() external payable {}
}

