pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(amount) {} catch { return; }
        uint256 beforeBalance = address(c).balance;
        uint256 returned;
        try c.ethBalance() returns (uint256 __r) { returned = __r; } catch { return; }
        assertTrue(returned == beforeBalance && returned == address(c).balance);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
